<script setup lang="ts">import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';import {Head,useForm} from '@inertiajs/vue3';const props=defineProps<{schoolYear?:any,defaults?:any}>();const form=useForm({name:props.schoolYear?.name||'',start_date:props.schoolYear?.start_date||'',end_date:props.schoolYear?.end_date||'',timezone:props.schoolYear?.timezone||props.defaults?.timezone||'America/Chicago',status:props.schoolYear?.status||'draft',instructional_day_target:props.schoolYear?.instructional_day_target||null});const submit=()=>props.schoolYear?form.patch(route('school-years.update',props.schoolYear.id)):form.post(route('school-years.store'));</script>
<template><Head :title="schoolYear?'Edit school year':'Add school year'"/><AuthenticatedLayout><h1 class="h2">{{schoolYear?'Edit school year':'Add school year'}}</h1><div class="alert alert-info mt-3">Activating this record transactionally closes any currently active school year.</div><div class="card"><form class="card-body" @submit.prevent="submit"><div class="row g-3"><div class="col-md-6"><label class="form-label">Name</label><input v-model="form.name" class="form-control" placeholder="2026–2027" required><div class="text-danger small">{{form.errors.name}}</div></div><div class="col-md-3"><label class="form-label">Start date</label><input v-model="form.start_date" type="date" class="form-control" required><div class="text-danger small">{{form.errors.start_date}}</div></div><div class="col-md-3"><label class="form-label">End date</label><input v-model="form.end_date" type="date" class="form-control" required><div class="text-danger small">{{form.errors.end_date}}</div></div><div class="col-md-4"><label class="form-label">Status</label><select v-model="form.status" class="form-select"><option>draft</option><option>active</option><option>closed</option><option>archived</option></select></div><div class="col-md-4"><label class="form-label">Timezone</label><input v-model="form.timezone" class="form-control" required></div><div class="col-md-4"><label class="form-label">Instructional-day target</label><input v-model="form.instructional_day_target" type="number" min="1" max="366" class="form-control"></div></div><button class="btn btn-primary mt-4" :disabled="form.processing">Save school year</button></form></div></AuthenticatedLayout></template>
